// A kit's generated text files carry a "Generated by … do not edit" header; the check fails one without it.
import { expect, test } from "bun:test";
import { cpSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";

const root = resolve(import.meta.dir, "..");
const command = process.env.TOKENS_BIN ? [resolve(process.env.TOKENS_BIN)] : ["bun", join(root, "bin/tokens.mjs")];
const engine = JSON.parse(readFileSync(join(root, "package.json"), "utf8")).version;
const run = (cwd: string, ...args: string[]) => Bun.spawnSync([...command, ...args], { cwd, stderr: "pipe" });
const read = (dir: string, file: string) => readFileSync(join(dir, file), "utf8");
const line = (target: string) =>
  `Generated by kumiko (tokens ${engine}) from acme 1.2.3, output ${target}: do not edit; change the kit's inputs and rebuild.`;

const files: Record<string, string> = {
  "out/a.css": ":root { --a: 1px; }\n",
  "out/b.yaml": "key: value\n",
  "out/c.md": "---\ntitle: C\n---\n\n# C\n",
  "out/d.html": "<!doctype html>\n<html></html>\n",
  "out/e.json": '{"a":1}\n',
  "out/f.sh": "#!/bin/sh\necho hi\n",
  "out/g.svg": '<?xml version="1.0"?>\n<svg/>\n',
  "out/h.txt": "plain\n",
};
const filesTarget = `export default { name: "files", build: async () => ${JSON.stringify(
  Object.entries(files).map(([path, content]) => ({ path, content })))} };\n`;
const kitProject = (kit = true) => {
  const dir = mkdtempSync(join(tmpdir(), "tokens-header-"));
  cpSync(join(root, "tests/fixture"), dir, { recursive: true });
  rmSync(join(dir, "tokens/stack.tokens.json"));
  writeFileSync(join(dir, "files.mjs"), filesTarget);
  writeFileSync(join(dir, "tokens.config.mjs"),
    `export default { targets: ["./files.mjs"]${kit ? ', kit: { name: "acme" }' : ""} };\n`);
  if (kit) writeFileSync(join(dir, "VERSION"), "1.2.3\n");
  return dir;
};

test("a kit's text outputs start with the header, placed by file type", () => {
  const dir = kitProject();
  expect(run(dir).exitCode).toBe(0);
  const h = line("files");
  expect(read(dir, "out/a.css")).toBe(`/* ${h} */\n${files["out/a.css"]}`);
  expect(read(dir, "out/b.yaml")).toBe(`# ${h}\n${files["out/b.yaml"]}`);
  expect(read(dir, "out/c.md")).toBe(`---\ntitle: C\n---\n<!-- ${h} -->\n\n# C\n`);
  expect(read(dir, "out/d.html")).toBe(`<!doctype html>\n<!-- ${h} -->\n<html></html>\n`);
  expect(read(dir, "out/f.sh")).toBe(`#!/bin/sh\n# ${h}\necho hi\n`);
  expect(read(dir, "out/g.svg")).toBe(`<?xml version="1.0"?>\n<!-- ${h} -->\n<svg/>\n`);
});

test("json and unknown extensions get no header", () => {
  const dir = kitProject();
  expect(run(dir).exitCode).toBe(0);
  expect(read(dir, "out/e.json")).toBe(files["out/e.json"]);
  expect(read(dir, "out/h.txt")).toBe(files["out/h.txt"]);
});

test("with no kit, nothing gets a header", () => {
  const dir = kitProject(false);
  expect(run(dir).exitCode).toBe(0);
  for (const path of Object.keys(files)) expect(read(dir, path)).toBe(files[path]);
});

test("--check passes on a built kit", () => {
  const dir = kitProject();
  run(dir);
  expect(run(dir, "--check").exitCode).toBe(0);
});

test("--check fails a kit output whose header is gone, naming the path", () => {
  const dir = kitProject();
  run(dir);
  writeFileSync(join(dir, "out/a.css"), files["out/a.css"]);
  const result = run(dir, "--check");
  expect(result.exitCode).toBe(1);
  const message = result.stderr.toString();
  expect(message).toContain("out/a.css");
  expect(message).toContain("header");
});

test("--check fails a header past the tenth line, naming the path", () => {
  const dir = kitProject();
  run(dir);
  writeFileSync(join(dir, "out/b.yaml"), `${"x: 1\n".repeat(10)}# ${line("files")}\n${files["out/b.yaml"]}`);
  const result = run(dir, "--check");
  expect(result.exitCode).toBe(1);
  expect(result.stderr.toString()).toContain("out/b.yaml");
  expect(result.stderr.toString()).toContain("header");
});

test("a header that would land past the tenth line fails the build", () => {
  const dir = kitProject();
  writeFileSync(join(dir, "files.mjs"), `export default { name: "files", build: async () => [{ path: "long.md", content: "---\\n${"k: v\\n".repeat(12)}---\\nbody\\n" }] };\n`);
  const result = run(dir);
  expect(result.exitCode).toBe(1);
  expect(result.stderr.toString()).toContain("long.md");
});
